public class MonetaryConversionTests {
  private readonly MonetaryConversionService service=new();
  [Fact] public void Same_currency_uses_decimal_factor_one(){var r=service.Convert(new(100m,"USD","USD",null,null));Assert.True(r.Success);Assert.Equal(100m,r.ConvertedAmount);Assert.Equal(1m,r.ExchangeRateUsed);Assert.Equal("SAME_CURRENCY",r.ExchangeRateSource);}
  [Fact] public void Explicit_rate_converts_and_preserves_source(){var r=service.Convert(new(100m,"USD","MXN",17.50m,"TradeOperation.ExchangeRate"));Assert.True(r.Success);Assert.Equal(1750m,r.ConvertedAmount);Assert.Equal(17.50m,r.ExchangeRateUsed);Assert.Equal("TradeOperation.ExchangeRate",r.ExchangeRateSource);}
  [Theory] [InlineData(0)] [InlineData(-1)] public void Non_positive_rate_is_rejected(decimal rate){var r=service.Convert(new(100m,"USD","MXN",rate,"PEDIMENTO:test.pdf"));Assert.False(r.Success);Assert.Null(r.ConvertedAmount);Assert.Equal("VALUATION_EXCHANGE_RATE_REQUIRED",r.ErrorCode);}
  [Theory] [InlineData("")] [InlineData(" ")] public void Missing_currency_is_not_invented(string currency){var r=service.Convert(new(100m,currency,"MXN",17.5m,"source"));Assert.False(r.Success);Assert.Null(r.ConvertedAmount);Assert.Equal("VALUATION_CURRENCY_REQUIRED",r.ErrorCode);}
  [Fact] public void Unknown_currency_is_not_invented(){var r=service.Convert(new(100m,"ZZZ","MXN",17.5m,"source"));Assert.False(r.Success);Assert.Null(r.ConvertedAmount);Assert.Equal("VALUATION_CURRENCY_UNSUPPORTED",r.ErrorCode);}
  [Fact] public void Null_currency_is_controlled_when_conversion_would_be_needed(){var r=service.Convert(new(100m,null!,"MXN",17.5m,"source"));Assert.False(r.Success);Assert.Null(r.ConvertedAmount);Assert.Equal("VALUATION_CURRENCY_REQUIRED",r.ErrorCode);}
  [Fact] public void Conversion_rounding_is_decimal_and_deterministic(){var r=service.Convert(new(1m,"USD","MXN",1.23456789m,"source"));Assert.Equal(1.234568m,r.ConvertedAmount);}
}

public class CustomsValuationEngineTests {
  [Fact] public async Task Match_persists_formula_components_evidence_and_zero_difference(){await using var f=await ValuationFixture.Create();f.Add("COMMERCIAL_INVOICE",DocumentFieldCodes.TotalAmount,1000m,"USD");f.Add("TRANSPORT_SERVICE_INVOICE",DocumentFieldCodes.FreightAmount,100m,"USD");f.Add("INSURANCE_INVOICE",DocumentFieldCodes.InsuranceAmount,50m,"USD");f.Add("PEDIMENTO",DocumentFieldCodes.DeclaredCustomsValue,1150m,"USD");await f.Save();var r=await f.Calculate();Assert.Equal(ValuationOutcome.MATCH,r.Outcome);Assert.Equal(1150m,r.CalculatedCustomsValue);Assert.Equal(1150m,r.DeclaredCustomsValue);Assert.Equal(0m,r.DifferenceAmount);Assert.Equal(0m,r.DifferencePercent);Assert.Contains("1000 + 100 + 50 = 1150 USD",r.Formula);Assert.Equal(3,r.Components.Count);Assert.All(r.Components,x=>Assert.NotEmpty(x.Evidence));Assert.Equal(.01m,r.AbsoluteToleranceUsed);Assert.Equal(.01m,r.PercentToleranceUsed);}
  [Fact] public async Task Mismatch_preserves_technical_values_without_creating_legal_finding(){await using var f=await ValuationFixture.Create();f.Add("COMMERCIAL_INVOICE",DocumentFieldCodes.TotalAmount,1000m,"USD");f.Add("TRANSPORT_SERVICE_INVOICE",DocumentFieldCodes.FreightAmount,100m,"USD");f.Add("INSURANCE_INVOICE",DocumentFieldCodes.InsuranceAmount,50m,"USD");f.Add("PEDIMENTO",DocumentFieldCodes.DeclaredCustomsValue,1200m,"USD");await f.AddLegalResult();await f.Save();var r=await f.Calculate();Assert.Equal(ValuationOutcome.MISMATCH,r.Outcome);Assert.Equal(1150m,r.CalculatedCustomsValue);Assert.Equal(1200m,r.DeclaredCustomsValue);Assert.Equal(-50m,r.DifferenceAmount);Assert.Equal(50m/1200m*100m,r.DifferencePercent);Assert.NotEmpty(r.Formula);Assert.NotEmpty(r.Explanation);Assert.Equal(.01m,r.AbsoluteToleranceUsed);Assert.Equal(LegalOutcome.COMPLIANT,(await f.Db.AuditResults.SingleAsync()).Outcome);Assert.Empty(await f.Db.Findings.ToListAsync());}
  [Fact] public async Task Missing_exchange_rate_produces_insufficient_evidence_without_zero_substitution(){await using var f=await ValuationFixture.Create();f.Add("COMMERCIAL_INVOICE",DocumentFieldCodes.TotalAmount,1000m,"USD");f.Add("TRANSPORT_SERVICE_INVOICE",DocumentFieldCodes.FreightAmount,100m,"USD");f.Add("PEDIMENTO",DocumentFieldCodes.DeclaredCustomsValue,19250m,"MXN");await f.Save();var r=await f.Calculate();Assert.Equal(ValuationOutcome.INSUFFICIENT_EVIDENCE,r.Outcome);Assert.Null(r.CalculatedCustomsValue);Assert.Null(r.TransactionValueConverted);}
  [Fact] public async Task Declared_value_without_base_produces_insufficient_evidence(){await using var f=await ValuationFixture.Create();f.Add("PEDIMENTO",DocumentFieldCodes.DeclaredCustomsValue,1200m,"USD");await f.Save();var r=await f.Calculate();Assert.Equal(ValuationOutcome.INSUFFICIENT_EVIDENCE,r.Outcome);Assert.Null(r.CalculatedCustomsValue);Assert.Null(r.TransactionValue);}
  [Fact] public async Task Unclassified_incrementable_is_visible_not_added_and_requires_manual_review(){await using var f=await ValuationFixture.Create();f.Add("COMMERCIAL_INVOICE",DocumentFieldCodes.TotalAmount,1000m,"USD");f.Add("INCREMENTABLE_INVOICE",DocumentFieldCodes.IncrementableTotal,100m,"USD","logistica.pdf");f.Add("PEDIMENTO",DocumentFieldCodes.DeclaredCustomsValue,1000m,"USD");await f.Save();var r=await f.Calculate();var c=Assert.Single(r.Components,x=>x.ComponentType==ValuationComponentType.UNCLASSIFIED_INCREMENTABLE);Assert.Equal(ValuationTreatment.INFORMATIONAL,c.Treatment);Assert.Equal(100m,c.ConvertedAmount);Assert.Equal(0m,r.IncrementablesTotal);Assert.Equal(ValuationOutcome.MANUAL_REVIEW,r.Outcome);Assert.True(r.IsManualReviewRequired);}
  [Fact] public async Task Same_freight_supported_by_transport_invoice_and_payment_is_counted_once_not_three_times(){await using var f=await ValuationFixture.Create();f.Add("COMMERCIAL_INVOICE",DocumentFieldCodes.TotalAmount,1000m,"USD");f.Add("TRANSPORT_DOCUMENT",DocumentFieldCodes.FreightAmount,368m,"USD","awb.pdf");f.Add("TRANSPORT_SERVICE_INVOICE",DocumentFieldCodes.FreightAmount,368m,"USD","freight-invoice.pdf");f.Add("INCREMENTABLE_PAYMENT",DocumentFieldCodes.PaymentAmount,368m,"USD","freight-payment.pdf");f.Add("PEDIMENTO",DocumentFieldCodes.DeclaredCustomsValue,1368m,"USD");await f.Save();var r=await f.Calculate();var freight=Assert.Single(r.Components,x=>x.ComponentType==ValuationComponentType.FREIGHT);Assert.Equal(368m,freight.ConvertedAmount);Assert.Equal(368m,r.FreightTotal);Assert.Equal(368m,r.IncrementablesTotal);Assert.Equal(3,freight.Evidence.Count);Assert.Contains(freight.Evidence,x=>x.EvidenceRole==EvidenceRole.PRIMARY);Assert.Contains(freight.Evidence,x=>x.EvidenceRole==EvidenceRole.SUPPORTING);Assert.Contains(freight.Evidence,x=>x.EvidenceRole==EvidenceRole.PAYMENT);}
  [Fact] public async Task Same_file_hash_never_duplicates_an_economic_component_or_amount(){await using var f=await ValuationFixture.Create();f.Add("COMMERCIAL_INVOICE",DocumentFieldCodes.TotalAmount,1000m,"USD");f.Add("TRANSPORT_SERVICE_INVOICE",DocumentFieldCodes.FreightAmount,100m,"USD","copy-a.pdf","same-hash");f.Add("TRANSPORT_SERVICE_INVOICE",DocumentFieldCodes.FreightAmount,100m,"USD","copy-b.pdf","same-hash");f.Add("PEDIMENTO",DocumentFieldCodes.DeclaredCustomsValue,1100m,"USD");await f.Save();var r=await f.Calculate();Assert.Single(r.Components,x=>x.ComponentType==ValuationComponentType.FREIGHT);Assert.Equal(100m,r.FreightTotal);Assert.Single(r.Components.Single(x=>x.ComponentType==ValuationComponentType.FREIGHT).Evidence);}
  [Fact] public async Task Component_supports_all_evidence_roles_without_replicating_value(){await using var f=await ValuationFixture.Create();f.Add("COMMERCIAL_INVOICE",DocumentFieldCodes.TotalAmount,1000m,"USD");f.Add("TRANSPORT_SERVICE_INVOICE",DocumentFieldCodes.FreightAmount,368m,"USD");f.Add("TRANSPORT_DOCUMENT",DocumentFieldCodes.FreightAmount,368m,"USD");f.Add("INCREMENTABLE_PAYMENT",DocumentFieldCodes.PaymentAmount,368m,"USD");f.Add("PEDIMENTO",DocumentFieldCodes.DeclaredFreight,368m,"USD",fields:[(DocumentFieldCodes.DeclaredCustomsValue,1368m,"USD")]);await f.Save();var r=await f.Calculate();var freight=Assert.Single(r.Components,x=>x.ComponentType==ValuationComponentType.FREIGHT);Assert.Equal(Enum.GetValues<EvidenceRole>().Order(),freight.Evidence.Select(x=>x.EvidenceRole).Order());Assert.Equal(368m,r.FreightTotal);}
  [Theory]
  [InlineData(ValuationComponentType.FREIGHT,DocumentFieldCodes.FreightAmount,"TRANSPORT_SERVICE_INVOICE")]
  [InlineData(ValuationComponentType.INSURANCE,DocumentFieldCodes.InsuranceAmount,"INSURANCE_INVOICE")]
  [InlineData(ValuationComponentType.PACKAGING,DocumentFieldCodes.PackagingAmount,"INCREMENTABLE_INVOICE")]
  [InlineData(ValuationComponentType.OTHER_INCREMENTABLE,DocumentFieldCodes.OtherIncrementableAmount,"INCREMENTABLE_INVOICE")]
  public async Task Each_incrementable_is_evidenced_converted_and_added_once(ValuationComponentType type,string code,string documentType){await using var f=await ValuationFixture.Create(exchangeRate:17.5m);f.Add("COMMERCIAL_INVOICE",DocumentFieldCodes.TotalAmount,100m,"USD");f.Add(documentType,code,10m,"USD");f.Add("PEDIMENTO",DocumentFieldCodes.DeclaredCustomsValue,1925m,"MXN");await f.Save();var r=await f.Calculate();var component=Assert.Single(r.Components,x=>x.ComponentType==type);Assert.Equal(175m,component.ConvertedAmount);Assert.Equal("TradeOperation.ExchangeRate",component.ExchangeRateSource);Assert.NotEmpty(component.Evidence);Assert.Equal(175m,r.IncrementablesTotal);Assert.Equal(ValuationOutcome.MATCH,r.Outcome);}
  [Fact] public async Task Mv_mve_participates_as_non_infallible_support(){await using var f=await ValuationFixture.Create();f.Add("MANIFESTACION_VALOR_MV_MVE",DocumentFieldCodes.TransactionValue,1000m,"USD",fields:[(DocumentFieldCodes.FreightAmount,100m,"USD"),(DocumentFieldCodes.InsuranceAmount,50m,"USD")]);f.Add("PEDIMENTO",DocumentFieldCodes.DeclaredCustomsValue,1150m,"USD");await f.Save();var r=await f.Calculate();Assert.Equal(ValuationOutcome.MATCH,r.Outcome);Assert.Equal(1000m,r.TransactionValue);Assert.Contains(r.Components,x=>x.ComponentType==ValuationComponentType.FREIGHT&&x.Evidence.Any(e=>e.EvidenceRole==EvidenceRole.SUPPORTING));}
  [Fact] public async Task Trade_operation_exchange_rate_is_traceable_on_original_and_converted_amounts(){await using var f=await ValuationFixture.Create(exchangeRate:17.5m);f.Add("COMMERCIAL_INVOICE",DocumentFieldCodes.TotalAmount,100m,"USD");f.Add("PEDIMENTO",DocumentFieldCodes.DeclaredCustomsValue,1750m,"MXN");await f.Save();var r=await f.Calculate();var c=Assert.Single(r.Components);Assert.Equal("USD",c.Currency);Assert.Equal(17.5m,c.ExchangeRate);Assert.Equal("TradeOperation.ExchangeRate",c.ExchangeRateSource);Assert.Equal(1750m,c.ConvertedAmount);Assert.Equal(17.5m,r.ExchangeRate);Assert.Equal("TradeOperation.ExchangeRate",r.ExchangeRateSource);}
  [Fact] public async Task Recalculation_appends_version_and_preserves_v1(){await using var f=await ValuationFixture.Create();f.Add("COMMERCIAL_INVOICE",DocumentFieldCodes.TotalAmount,1000m,"USD");var ped=f.Add("PEDIMENTO",DocumentFieldCodes.DeclaredCustomsValue,1000m,"USD");await f.Save();var v1=await f.Calculate();ped.Fields.Single().RawValue=ped.Fields.Single().NormalizedValue="1100";await f.Save();var v2=await f.Calculate();f.Db.ChangeTracker.Clear();var history=await f.Db.CustomsValuationCalculations.OrderBy(x=>x.CalculationVersion).ToListAsync();Assert.Equal(2,history.Count);Assert.Equal(1,v1.CalculationVersion);Assert.Equal(2,v2.CalculationVersion);Assert.Equal(1000m,history[0].DeclaredCustomsValue);Assert.Equal(1100m,history[1].DeclaredCustomsValue);Assert.Equal(new[]{"VALUATION_STARTED","VALUATION_COMPLETED","VALUATION_STARTED","VALUATION_RECALCULATED"},await f.Db.SystemAuditLogs.OrderBy(x=>x.Timestamp).Select(x=>x.Action).ToArrayAsync());}
}

public class ContributionReconciliationTests {
  [Theory] [InlineData("1000","1000",ContributionOutcome.RECONCILED,"0")] [InlineData("1000","900",ContributionOutcome.MISMATCH,"100")] [InlineData("1000",null,ContributionOutcome.INSUFFICIENT_EVIDENCE,null)]
  public async Task Declared_and_paid_amounts_reconcile_without_legal_side_effects(string declared,string? paid,ContributionOutcome expected,string? difference){await using var f=await ValuationFixture.Create();f.AddContribution("IGI",declared,paid);await f.AddLegalResult();await f.Save();var r=await f.Reconcile();var line=Assert.Single(r.Lines);Assert.Equal(expected,line.Outcome);Assert.Equal(difference is null?null:decimal.Parse(difference),line.DifferenceDeclaredVsPaid);Assert.Equal(LegalOutcome.COMPLIANT,(await f.Db.AuditResults.SingleAsync()).Outcome);Assert.Empty(await f.Db.Findings.ToListAsync());}
  [Fact] public async Task Missing_rate_is_not_calculated_and_unknown_code_is_preserved(){await using var f=await ValuationFixture.Create();f.AddContribution("XYZ","1000",null,includeBase:true);await f.Save();var r=await f.Reconcile();var line=Assert.Single(r.Lines);Assert.Equal("XYZ",line.RawContributionCode);Assert.Equal("XYZ",line.ContributionCode);Assert.Equal(1000m,line.TaxBase);Assert.Null(line.Rate);Assert.Null(line.CalculatedAmount);Assert.Equal(ContributionOutcome.INSUFFICIENT_EVIDENCE,line.Outcome);}
  [Fact] public async Task Reconciliation_logs_existing_user_without_foreign_key_failure(){await using var f=await ValuationFixture.Create();f.AddContribution("IVA","1000","1000");await f.Save();await f.Reconcile();var logs=await f.Db.SystemAuditLogs.Where(x=>x.Action.StartsWith("CONTRIBUTION_")).ToListAsync();Assert.Equal(2,logs.Count);Assert.All(logs,x=>Assert.Equal(f.User.Id,x.UserId));}
}

public class Sprint2CrossValidationRuleTests {
  private static readonly (string Code,string Source,string SourceField,string Target,string TargetField,CrossComparisonType Comparison)[] Expected=[
    ("CROSS-FREIGHT-INV-PED-001","TRANSPORT_SERVICE_INVOICE",DocumentFieldCodes.FreightAmount,"PEDIMENTO",DocumentFieldCodes.DeclaredFreight,CrossComparisonType.CURRENCY_AMOUNT),
    ("CROSS-FREIGHT-PAY-INV-001","INCREMENTABLE_PAYMENT",DocumentFieldCodes.PaymentAmount,"TRANSPORT_SERVICE_INVOICE",DocumentFieldCodes.FreightAmount,CrossComparisonType.CURRENCY_AMOUNT),
    ("CROSS-FREIGHT-TR-INV-001","TRANSPORT_DOCUMENT",DocumentFieldCodes.TransportReference,"TRANSPORT_SERVICE_INVOICE",DocumentFieldCodes.TransportReference,CrossComparisonType.NORMALIZED_IDENTIFIER),
    ("CROSS-INS-POL-PED-001","INSURANCE_POLICY",DocumentFieldCodes.InsuranceAmount,"PEDIMENTO",DocumentFieldCodes.DeclaredInsurance,CrossComparisonType.CURRENCY_AMOUNT),
    ("CROSS-INS-INV-PED-001","INSURANCE_INVOICE",DocumentFieldCodes.InsuranceAmount,"PEDIMENTO",DocumentFieldCodes.DeclaredInsurance,CrossComparisonType.CURRENCY_AMOUNT),
    ("CROSS-INS-PAY-INV-001","INSURANCE_PAYMENT",DocumentFieldCodes.PaymentAmount,"INSURANCE_INVOICE",DocumentFieldCodes.InsuranceAmount,CrossComparisonType.CURRENCY_AMOUNT),
    ("CROSS-INC-INV-PED-001","INCREMENTABLE_INVOICE",DocumentFieldCodes.IncrementableTotal,"PEDIMENTO",DocumentFieldCodes.IncrementableTotal,CrossComparisonType.CURRENCY_AMOUNT),
    ("CROSS-INC-PAY-INV-001","INCREMENTABLE_PAYMENT",DocumentFieldCodes.PaymentAmount,"INCREMENTABLE_INVOICE",DocumentFieldCodes.IncrementableTotal,CrossComparisonType.CURRENCY_AMOUNT),
    ("CROSS-VAL-MV-PED-001","MANIFESTACION_VALOR_MV_MVE",DocumentFieldCodes.DeclaredCustomsValue,"PEDIMENTO",DocumentFieldCodes.DeclaredCustomsValue,CrossComparisonType.CURRENCY_AMOUNT),
    ("CROSS-VAL-COMMERCIAL-001","COMMERCIAL_INVOICE",DocumentFieldCodes.TotalAmount,"PEDIMENTO",DocumentFieldCodes.CommercialValue,CrossComparisonType.CURRENCY_AMOUNT),
    ("CROSS-VAL-COVE-001","COVE_ACK",DocumentFieldCodes.TotalAmount,"COMMERCIAL_INVOICE",DocumentFieldCodes.TotalAmount,CrossComparisonType.CURRENCY_AMOUNT)
  ];
  [Fact] public async Task Seed_contains_exactly_the_eleven_versioned_sprint2_rules(){using var factory=new SaceFactory();_ = factory.CreateClient();await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<SaceDbContext>();var codes=Expected.Select(x=>x.Code).ToArray();var rows=await db.CrossValidationRules.Where(x=>codes.Contains(x.Code)).OrderBy(x=>x.Code).ToListAsync();Assert.Equal(11,rows.Count);Assert.Equal(11,rows.Select(x=>new{x.Code,x.Version}).Distinct().Count());Assert.All(rows,x=>Assert.True(x.IsActive));foreach(var expected in Expected){var row=Assert.Single(rows,x=>x.Code==expected.Code);Assert.Equal(1,row.Version);Assert.Equal(expected.Source,row.SourceDocumentTypeCode);Assert.Equal(expected.SourceField,row.SourceFieldCode);Assert.Equal(expected.Target,row.TargetDocumentTypeCode);Assert.Equal(expected.TargetField,row.TargetFieldCode);Assert.Equal(expected.Comparison,row.ComparisonType);Assert.Equal(expected.Comparison==CrossComparisonType.CURRENCY_AMOUNT?(decimal?)0.01m:null,row.AbsoluteTolerance);Assert.Null(row.PercentTolerance);Assert.Equal(MissingEvidenceBehavior.INSUFFICIENT_EVIDENCE,row.MissingEvidenceBehavior);}}
  [Theory]
  [InlineData("FREIGHT","TRANSPORT_SERVICE_INVOICE",DocumentFieldCodes.FreightAmount,"PEDIMENTO",DocumentFieldCodes.DeclaredFreight)]
  [InlineData("INSURANCE","INSURANCE_INVOICE",DocumentFieldCodes.InsuranceAmount,"PEDIMENTO",DocumentFieldCodes.DeclaredInsurance)]
  [InlineData("INCREMENTABLES","INCREMENTABLE_INVOICE",DocumentFieldCodes.IncrementableTotal,"PEDIMENTO",DocumentFieldCodes.IncrementableTotal)]
  [InlineData("VALUATION","MANIFESTACION_VALOR_MV_MVE",DocumentFieldCodes.DeclaredCustomsValue,"PEDIMENTO",DocumentFieldCodes.DeclaredCustomsValue)]
  public async Task Representative_groups_produce_match_and_mismatch(string group,string sourceType,string sourceField,string targetType,string targetField){Assert.Equal(CrossValidationOutcome.MATCH,await Run(group,sourceType,sourceField,targetType,targetField,"100","100"));Assert.Equal(CrossValidationOutcome.MISMATCH,await Run(group,sourceType,sourceField,targetType,targetField,"100","90"));}
  private static async Task<CrossValidationOutcome> Run(string group,string sourceType,string sourceField,string targetType,string targetField,string sourceValue,string targetValue){await using var connection=new SqliteConnection("DataSource=:memory:");await connection.OpenAsync();await using var db=new SaceDbContext(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite(connection).Options);await db.Database.EnsureCreatedAsync();var user=new User{Name="Cross",Email=$"{Guid.NewGuid():N}@example.invalid",PasswordHash="x"};var op=new TradeOperation{Folio=$"CROSS-{Guid.NewGuid():N}",PedimentoNumber="26",Period="2026-10",OperationDate=DateTime.UtcNow,TariffFraction="1"};var st=new DocumentType{Code=sourceType,Name=sourceType};var tt=new DocumentType{Code=targetType,Name=targetType};var sd=new OperationDocument{TradeOperation=op,DocumentType=st,OriginalFileName="source.pdf",UploadedBy=user.Id};var td=new OperationDocument{TradeOperation=op,DocumentType=tt,OriginalFileName="target.pdf",UploadedBy=user.Id};sd.Fields.Add(Field(sourceField,sourceValue));td.Fields.Add(Field(targetField,targetValue));var rule=new CrossValidationRule{Code=$"TEST-{group}",Name=group,SourceDocumentTypeCode=sourceType,SourceFieldCode=sourceField,TargetDocumentTypeCode=targetType,TargetFieldCode=targetField,ComparisonType=CrossComparisonType.CURRENCY_AMOUNT,MissingEvidenceBehavior=MissingEvidenceBehavior.INSUFFICIENT_EVIDENCE};db.AddRange(user,op,st,tt,sd,td,rule);await db.SaveChangesAsync();return Assert.Single(await new CrossValidationEngine(db,new NoopExtractor()).ExecuteAsync(op.Id,null,user.Id)).Outcome;}
  private static DocumentField Field(string code,string value)=>new(){FieldCode=code,RawValue=value,NormalizedValue=value,DataType=DocumentFieldDataType.DECIMAL,Currency="USD",ExtractionMethod=ExtractionMethod.MANUAL,Confidence=.95};
  private sealed class NoopExtractor:IDocumentFieldExtractor { public Task<int> ExtractDocumentAsync(Guid documentId,Guid userId,CancellationToken ct=default)=>Task.FromResult(0);public Task<int> ExtractOperationAsync(Guid operationId,Guid userId,CancellationToken ct=default)=>Task.FromResult(0); }
}

public class Sprint2FieldExtractionTests {
  [Fact] public async Task Pedimento_preserves_existing_codes_and_extracts_sprint2_valuation_fields(){await using var connection=new SqliteConnection("DataSource=:memory:");await connection.OpenAsync();await using var db=new SaceDbContext(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite(connection).Options);await db.Database.EnsureCreatedAsync();var user=new User{Name="Fields",Email="sprint2-fields@example.invalid",PasswordHash="x"};var op=new TradeOperation{Folio="FIELDS-S2",PedimentoNumber="26 16 3108 6002948",Period="2026-10",OperationDate=DateTime.UtcNow,TariffFraction="40169304",CommercialValue=1000m,Currency="USD",ExchangeRate=17.5m,DeclaredCustomsValueMxn=20125m};var type=new DocumentType{Code="PEDIMENTO",Name="Pedimento"};var doc=new OperationDocument{TradeOperation=op,DocumentType=type,OriginalFileName="pedimento.pdf",Extension=".pdf",FilePath="synthetic/pedimento.pdf",UploadedBy=user.Id};db.AddRange(user,op,type,doc);await db.SaveChangesAsync();var text="Flete declarado: USD 100\nSeguro declarado: USD 50\nEmbalaje declarado: USD 0\nOtros incrementables declarados: USD 0\nValor en aduana declarado: MXN 20125\nTipo de cambio: 17.50";var extractor=new DocumentFieldExtractor(db,new StubStorage(),new StubPdfText(text),new FieldNormalizationService());await extractor.ExtractDocumentAsync(doc.Id,user.Id);var fields=await db.DocumentFields.Where(x=>x.OperationDocumentId==doc.Id).ToListAsync();foreach(var code in new[]{DocumentFieldCodes.CommercialValue,DocumentFieldCodes.DeclaredFreight,DocumentFieldCodes.DeclaredInsurance,DocumentFieldCodes.DeclaredPackaging,DocumentFieldCodes.DeclaredOtherIncrementables,DocumentFieldCodes.DeclaredCustomsValue,DocumentFieldCodes.ExchangeRate})Assert.Contains(fields,x=>x.FieldCode==code);Assert.Contains(fields,x=>x.FieldCode==DocumentFieldCodes.PedimentoNumber&&x.ExtractionMethod==ExtractionMethod.EXISTING_METADATA);}
  [Fact] public async Task Contribution_pdf_fields_share_a_group_for_reconciliation(){await using var connection=new SqliteConnection("DataSource=:memory:");await connection.OpenAsync();await using var db=new SaceDbContext(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite(connection).Options);await db.Database.EnsureCreatedAsync();var user=new User{Name="Fields",Email="sprint2-contribution-fields@example.invalid",PasswordHash="x"};var op=new TradeOperation{Folio="FIELDS-CONTRIB",PedimentoNumber="26",Period="2026-10",OperationDate=DateTime.UtcNow,TariffFraction="1"};var type=new DocumentType{Code="PEDIMENTO",Name="Pedimento"};var doc=new OperationDocument{TradeOperation=op,DocumentType=type,OriginalFileName="pedimento.pdf",Extension=".pdf",FilePath="synthetic/pedimento.pdf",UploadedBy=user.Id};db.AddRange(user,op,type,doc);await db.SaveChangesAsync();var extractor=new DocumentFieldExtractor(db,new StubStorage(),new StubPdfText("Contribución: IVA\nBase de contribución: 1000\nTasa: 16\nContribución declarada: 160"),new FieldNormalizationService());await extractor.ExtractDocumentAsync(doc.Id,user.Id);var fields=await db.DocumentFields.Where(x=>x.OperationDocumentId==doc.Id&&x.GroupKey=="CONTRIBUTION-1").ToListAsync();Assert.Equal(4,fields.Count);Assert.Equal(new[]{DocumentFieldCodes.ContributionBase,DocumentFieldCodes.ContributionCode,DocumentFieldCodes.ContributionDeclaredAmount,DocumentFieldCodes.ContributionRate}.Order(),fields.Select(x=>x.FieldCode).Order());}
  private sealed class StubStorage:IFileStorageService { public Task<(string storedName,string relativePath)> SaveAsync(Guid operationId,string documentCode,IFormFile file,CancellationToken ct)=>throw new NotSupportedException();public Task<Stream?> OpenAsync(string relativePath,CancellationToken ct)=>Task.FromResult<Stream?>(new MemoryStream("%PDF-synthetic"u8.ToArray())); }
  private sealed class StubPdfText(string value):IPdfTextExtractor { public Task<string> ExtractAsync(Stream stream,CancellationToken ct)=>Task.FromResult(value); }
}

public sealed class ValuationFixture : IAsyncDisposable {
  private readonly SqliteConnection connection;private readonly IConfiguration config;private readonly Dictionary<string,DocumentType> types=[];
  public SaceDbContext Db {get;} public User User {get;} public TradeOperation Operation {get;}
  private ValuationFixture(SqliteConnection connection,SaceDbContext db,IConfiguration config,User user,TradeOperation operation){this.connection=connection;Db=db;this.config=config;User=user;Operation=operation;}
  public static async Task<ValuationFixture> Create(decimal? exchangeRate=null){var connection=new SqliteConnection("DataSource=:memory:");await connection.OpenAsync();var db=new SaceDbContext(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite(connection).Options);await db.Database.EnsureCreatedAsync();var config=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"Valuation:AbsoluteTolerance","0.01"},{"Valuation:PercentTolerance","0.01"},{"Contribution:AbsoluteTolerance","0.01"},{"Contribution:EnableTechnicalRateCalculation","false"}}).Build();var user=new User{Name="Sprint 2",Email=$"{Guid.NewGuid():N}@example.invalid",PasswordHash="x"};var op=new TradeOperation{Folio=$"VAL-{Guid.NewGuid():N}",PedimentoNumber="26",Period="2026-10",OperationDate=new DateTime(2026,10,1,0,0,0,DateTimeKind.Utc),TariffFraction="1",ExchangeRate=exchangeRate};db.AddRange(user,op);await db.SaveChangesAsync();return new(connection,db,config,user,op);}
  public OperationDocument Add(string typeCode,string fieldCode,decimal amount,string? currency,string file="document.pdf",string? hash=null,(string Code,decimal Amount,string? Currency)[]? fields=null){if(!types.TryGetValue(typeCode,out var type)){type=new DocumentType{Code=typeCode,Name=typeCode};types[typeCode]=type;Db.DocumentTypes.Add(type);}var doc=new OperationDocument{TradeOperationId=Operation.Id,DocumentType=type,OriginalFileName=file,StoredFileName=file,MimeType="application/pdf",Extension=".pdf",FilePath=$"synthetic/{file}",FileSize=1,UploadedBy=User.Id,FileHash=hash};doc.Fields.Add(Field(fieldCode,amount,currency));foreach(var extra in fields??[])doc.Fields.Add(Field(extra.Code,extra.Amount,extra.Currency));Db.OperationDocuments.Add(doc);return doc;}
  public void AddContribution(string code,string declared,string? paid,bool includeBase=false){var ped=Add("PEDIMENTO",DocumentFieldCodes.ContributionDeclaredAmount,decimal.Parse(declared),"MXN","pedimento.xml");var group="L1";ped.Fields.Single().GroupKey=group;ped.Fields.Add(new DocumentField{FieldCode=DocumentFieldCodes.ContributionCode,RawValue=code,NormalizedValue=code,DataType=DocumentFieldDataType.IDENTIFIER,ExtractionMethod=ExtractionMethod.XML,GroupKey=group});if(includeBase)ped.Fields.Add(new DocumentField{FieldCode=DocumentFieldCodes.ContributionBase,RawValue=declared,NormalizedValue=declared,DataType=DocumentFieldDataType.DECIMAL,Currency="MXN",ExtractionMethod=ExtractionMethod.XML,GroupKey=group});if(paid is not null){var payment=Add("PURCHASE_PAYMENT",DocumentFieldCodes.PaymentAmount,decimal.Parse(paid),"MXN","payment.pdf");payment.Fields.Add(new DocumentField{FieldCode=DocumentFieldCodes.ContributionCode,RawValue=code,NormalizedValue=code,DataType=DocumentFieldDataType.IDENTIFIER,ExtractionMethod=ExtractionMethod.PDF_TEXT});}}
  public async Task AddLegalResult(){var audit=new Audit{Number=$"LEGAL-{Guid.NewGuid():N}",TradeOperationId=Operation.Id,AuditType=AuditType.Legal,Status=AuditStatus.Completed,CreatedBy=User.Id};Db.AuditResults.Add(new AuditResult{Audit=audit,RuleId="LEGAL-KEEP",Status=ResultStatus.Valid,Outcome=LegalOutcome.COMPLIANT,IsIncludedInLegalCompliance=true});await Task.CompletedTask;}
  public Task Save()=>Db.SaveChangesAsync();
  public Task<CustomsValuationCalculation> Calculate()=>new CustomsValuationEngine(Db,new MonetaryConversionService(),config).CalculateAsync(Operation.Id,null,User.Id);
  public Task<ContributionCalculation> Reconcile()=>new ContributionReconciliationEngine(Db,config).ReconcileAsync(Operation.Id,null,User.Id);
  private static DocumentField Field(string code,decimal amount,string? currency)=>new(){FieldCode=code,RawValue=amount.ToString(System.Globalization.CultureInfo.InvariantCulture),NormalizedValue=amount.ToString(System.Globalization.CultureInfo.InvariantCulture),DataType=DocumentFieldDataType.DECIMAL,Currency=currency,Confidence=.95,ExtractionMethod=ExtractionMethod.MANUAL,IsManuallyConfirmed=true};
  public async ValueTask DisposeAsync(){await Db.DisposeAsync();await connection.DisposeAsync();}
}

public class Sprint2MigrationTests {
  private const string Sprint1="20261016183617_CrossValidationEngineV1";
  [Fact] public async Task Incremental_migration_preserves_sprint1_and_legal_data_and_down_is_scoped(){var path=TempDatabase();try{Guid userId,operationId,documentId,auditId,auditResultId,fieldId,crossResultId;await using(var db=Context(path)){var migrator=db.Database.GetService<IMigrator>();await migrator.MigrateAsync(Sprint1);var user=new User{Name="Migration",Email="sprint2@example.invalid",PasswordHash="x"};var op=new TradeOperation{Folio="SPRINT2-MIG",PedimentoNumber="26",Period="2026-10",OperationDate=DateTime.UtcNow,TariffFraction="1"};var type=new DocumentType{Code="MIG2",Name="Migration"};var doc=new OperationDocument{TradeOperation=op,DocumentType=type,OriginalFileName="synthetic.pdf",UploadedBy=user.Id};var field=new DocumentField{OperationDocument=doc,FieldCode=DocumentFieldCodes.TotalAmount,RawValue="100",NormalizedValue="100",DataType=DocumentFieldDataType.DECIMAL,ExtractionMethod=ExtractionMethod.MANUAL};var audit=new Audit{Number="LEGAL-MIG2",TradeOperation=op,AuditType=AuditType.Legal,Status=AuditStatus.Completed,CreatedBy=user.Id};var legal=new AuditResult{Audit=audit,RuleId="LEGAL-MIG2",Status=ResultStatus.Valid,Outcome=LegalOutcome.COMPLIANT,IsIncludedInLegalCompliance=true};var rule=new CrossValidationRule{Code="MIG2-CROSS",Name="Migration",SourceDocumentTypeCode="MIG2",SourceFieldCode=DocumentFieldCodes.TotalAmount,TargetDocumentTypeCode="MIG2",TargetFieldCode=DocumentFieldCodes.TotalAmount,ComparisonType=CrossComparisonType.EXACT_NUMERIC};var cross=new CrossValidationResult{TradeOperation=op,Audit=audit,CrossValidationRule=rule,RuleCode=rule.Code,RuleVersion=1,SourceDocument=doc,TargetDocument=doc,SourceField=field,TargetField=field,Outcome=CrossValidationOutcome.MATCH};db.AddRange(user,op,type,doc,field,audit,legal,rule,cross);await db.SaveChangesAsync();userId=user.Id;operationId=op.Id;documentId=doc.Id;auditId=audit.Id;auditResultId=legal.Id;fieldId=field.Id;crossResultId=cross.Id;await migrator.MigrateAsync();Assert.Equal(5,await CountTables(db,"CustomsValuationCalculations","CustomsValuationComponents","ValuationComponentEvidence","ContributionCalculations","ContributionLines"));Assert.True(await IndexExists(db,"IX_CustomsValuationComponents_CustomsValuationCalculationId_EconomicKey"));Assert.True(await ForeignKeys(db,"ValuationComponentEvidence")>=3);await migrator.MigrateAsync(Sprint1);}await using(var db=Context(path)){Assert.Equal(0,await CountTables(db,"CustomsValuationCalculations","CustomsValuationComponents","ValuationComponentEvidence","ContributionCalculations","ContributionLines"));Assert.True(await db.Users.AnyAsync(x=>x.Id==userId));Assert.True(await db.TradeOperations.AnyAsync(x=>x.Id==operationId));Assert.True(await db.OperationDocuments.AnyAsync(x=>x.Id==documentId));Assert.True(await db.Audits.AnyAsync(x=>x.Id==auditId));Assert.Equal(LegalOutcome.COMPLIANT,(await db.AuditResults.SingleAsync(x=>x.Id==auditResultId)).Outcome);Assert.True(await db.DocumentFields.AnyAsync(x=>x.Id==fieldId));Assert.True(await db.CrossValidationResults.AnyAsync(x=>x.Id==crossResultId));}}finally{DeleteDatabase(path);}}
  private static SaceDbContext Context(string path)=>new(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite($"Data Source={path}").Options);
  private static string TempDatabase(){var directory=Path.Combine(Path.GetTempPath(),$"sace-sprint2-{Guid.NewGuid():N}");Directory.CreateDirectory(directory);return Path.Combine(directory,"validation.db");}
  private static void DeleteDatabase(string path){SqliteConnection.ClearAllPools();var directory=Path.GetDirectoryName(path)!;if(Directory.Exists(directory)&&Path.GetFileName(directory).StartsWith("sace-sprint2-",StringComparison.Ordinal))Directory.Delete(directory,true);}
  private static async Task<long> CountTables(SaceDbContext db,params string[] names){var connection=(SqliteConnection)db.Database.GetDbConnection();if(connection.State!=ConnectionState.Open)await connection.OpenAsync();await using var command=connection.CreateCommand();command.CommandText=$"SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name IN ({string.Join(',',names.Select((_,i)=>$"$n{i}"))})";for(var i=0;i<names.Length;i++)command.Parameters.AddWithValue($"$n{i}",names[i]);return Convert.ToInt64(await command.ExecuteScalarAsync());}
  private static async Task<bool> IndexExists(SaceDbContext db,string name){var connection=(SqliteConnection)db.Database.GetDbConnection();if(connection.State!=ConnectionState.Open)await connection.OpenAsync();await using var command=connection.CreateCommand();command.CommandText="SELECT COUNT(*) FROM sqlite_master WHERE type='index' AND name=$name";command.Parameters.AddWithValue("$name",name);return Convert.ToInt64(await command.ExecuteScalarAsync())==1;}
  private static async Task<long> ForeignKeys(SaceDbContext db,string table){var connection=(SqliteConnection)db.Database.GetDbConnection();if(connection.State!=ConnectionState.Open)await connection.OpenAsync();await using var command=connection.CreateCommand();command.CommandText=$"PRAGMA foreign_key_list([{table}])";await using var reader=await command.ExecuteReaderAsync();long count=0;while(await reader.ReadAsync())count++;return count;}
}

public class Sprint2ApiSecurityTests {
  [Theory]
  [InlineData("GET","/api/operations/00000000-0000-0000-0000-000000000001/valuation")]
  [InlineData("GET","/api/operations/00000000-0000-0000-0000-000000000001/valuation/history")]
  [InlineData("POST","/api/operations/00000000-0000-0000-0000-000000000001/valuation/calculate")]
  [InlineData("GET","/api/operations/00000000-0000-0000-0000-000000000001/contributions")]
  [InlineData("POST","/api/operations/00000000-0000-0000-0000-000000000001/contributions/reconcile")]
  public async Task Sprint2_endpoints_require_jwt(string method,string path){using var factory=new SaceFactory();var response=await factory.CreateClient().SendAsync(new HttpRequestMessage(new HttpMethod(method),path));Assert.Equal(HttpStatusCode.Unauthorized,response.StatusCode);}
  [Fact] public async Task Invalid_session_is_unauthorized_without_stack_trace(){using var factory=new SaceFactory();var client=factory.CreateClient();client.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer","invalid-token");var response=await client.GetAsync("/api/operations/00000000-0000-0000-0000-000000000001/valuation");Assert.Equal(HttpStatusCode.Unauthorized,response.StatusCode);Assert.DoesNotContain("StackTrace",await response.Content.ReadAsStringAsync(),StringComparison.OrdinalIgnoreCase);}
  [Fact] public async Task Authenticated_unknown_operation_returns_structured_not_found(){using var factory=new SaceFactory();var client=factory.CreateClient();var login=await client.PostAsJsonAsync("/api/auth/login",new{email="admin@sace.local",password="Admin123!"});using var json=JsonDocument.Parse(await login.Content.ReadAsStringAsync());client.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",json.RootElement.GetProperty("token").GetString());var response=await client.GetAsync("/api/operations/00000000-0000-0000-0000-000000000001/valuation");Assert.Equal(HttpStatusCode.NotFound,response.StatusCode);var body=await response.Content.ReadAsStringAsync();Assert.Contains("NOT_FOUND",body);Assert.DoesNotContain("StackTrace",body,StringComparison.OrdinalIgnoreCase);}
  [Fact] public async Task All_sprint2_routes_return_structured_not_found_for_unknown_operation(){using var factory=new SaceFactory();var client=await Authenticated(factory);foreach(var (method,path) in new[]{("GET","valuation"),("GET","valuation/history"),("POST","valuation/calculate"),("GET","contributions"),("POST","contributions/reconcile")}){var response=await client.SendAsync(new HttpRequestMessage(new HttpMethod(method),$"/api/operations/00000000-0000-0000-0000-000000000001/{path}"));Assert.Equal(HttpStatusCode.NotFound,response.StatusCode);var body=await response.Content.ReadAsStringAsync();Assert.Contains("NOT_FOUND",body);Assert.DoesNotContain("StackTrace",body,StringComparison.OrdinalIgnoreCase);}}
  [Fact] public async Task Audit_continues_when_valuation_and_contributions_have_insufficient_evidence(){using var factory=new SaceFactory();var client=await Authenticated(factory);var created=await client.PostAsJsonAsync("/api/operations",new{pedimentoNumber="26 48 1234 6999901",operationDate="2026-10-01T12:00:00Z",period="2026-10",operationType="Importacion",pedimentoKey="IN",tariffFraction="85044001",originCountry="Estados Unidos",destinationCountry="México",customsRegime="Definitivo",isImmex=false,preferentialTreatment=false,commercialValue=1000,currency="USD"});created.EnsureSuccessStatusCode();using var createdJson=JsonDocument.Parse(await created.Content.ReadAsStringAsync());var id=createdJson.RootElement.GetProperty("id").GetString();var response=await client.PostAsync($"/api/operations/{id}/audit",null);Assert.Equal(HttpStatusCode.OK,response.StatusCode);using var body=JsonDocument.Parse(await response.Content.ReadAsStringAsync());Assert.Equal("INSUFFICIENT_EVIDENCE",body.RootElement.GetProperty("valuation").GetProperty("outcome").GetString());Assert.Equal("INSUFFICIENT_EVIDENCE",body.RootElement.GetProperty("contributions").GetProperty("status").GetString());Assert.Equal(JsonValueKind.Null,body.RootElement.GetProperty("valuationError").ValueKind);Assert.Equal(JsonValueKind.Null,body.RootElement.GetProperty("contributionError").ValueKind);}
  [Fact] public async Task Latest_and_history_endpoints_return_v2_without_mutating_v1(){using var factory=new SaceFactory();var client=await Authenticated(factory);Guid operationId;await using(var scope=factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<SaceDbContext>();var op=new TradeOperation{Folio="API-HISTORY",PedimentoNumber="26",Period="2026-10",OperationDate=DateTime.UtcNow,TariffFraction="1"};db.TradeOperations.Add(op);db.CustomsValuationCalculations.AddRange(new CustomsValuationCalculation{TradeOperation=op,CalculationVersion=1,DeclaredCustomsValue=100m,Outcome=ValuationOutcome.MATCH,Formula="v1"},new CustomsValuationCalculation{TradeOperation=op,CalculationVersion=2,DeclaredCustomsValue=120m,Outcome=ValuationOutcome.MISMATCH,Formula="v2"});await db.SaveChangesAsync();operationId=op.Id;}var latest=await client.GetAsync($"/api/operations/{operationId}/valuation");latest.EnsureSuccessStatusCode();using var latestJson=JsonDocument.Parse(await latest.Content.ReadAsStringAsync());Assert.Equal(2,latestJson.RootElement.GetProperty("calculationVersion").GetInt32());var history=await client.GetAsync($"/api/operations/{operationId}/valuation/history");history.EnsureSuccessStatusCode();using var historyJson=JsonDocument.Parse(await history.Content.ReadAsStringAsync());Assert.Equal(new[]{2,1},historyJson.RootElement.EnumerateArray().Select(x=>x.GetProperty("calculationVersion").GetInt32()));Assert.Equal(100m,historyJson.RootElement[1].GetProperty("declaredCustomsValue").GetDecimal());}
  private static async Task<HttpClient> Authenticated(SaceFactory factory){var client=factory.CreateClient();var login=await client.PostAsJsonAsync("/api/auth/login",new{email="admin@sace.local",password="Admin123!"});using var json=JsonDocument.Parse(await login.Content.ReadAsStringAsync());client.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",json.RootElement.GetProperty("token").GetString());return client;}
}
